  { v = "9.7.7.5", resumen = "Viajes: vuelos, posada, piedra de hogar, transportes y Cerca de ti más fiables. Versión de prueba.", grupos = {
      { t = "Viajes", "Un punto de vuelo solo cuenta como descubierto cuando el juego lo da como conocido, y si dos maestros de vuelo coinciden en el mismo sitio no se marca ninguno.", "La posada recomendada respeta la tuya si ya estás vinculado en una de la zona; si no, propone la más cercana a los pasos que vienen.", "La piedra de hogar dice si no la llevas o si no se sabe su estado.", "Al ir a otro continente o a otra zona con transporte directo, el aviso dice qué barco, zepelín, tranvía o nave celeste coger, de dónde sale y adónde llega, según tu facción." },
      { t = "Cerca de ti", "Solo vendedores, raros y bolsas de tu facción; las bolsas de misiones ya hechas no salen.", "Añade el instructor de clase si tienes hechizos recomendados sin aprender, y los objetivos de misión que tienes en el diario en esta zona.", "Si hay varias cosas en el mismo sitio, delante sale el número entre corchetes." },
      { t = "Falta probar en el juego", "Que los vuelos descubiertos y la posada recomendada son los de verdad, que la piedra de hogar dice bien su estado y que el aviso de transporte sale con el barco o zepelín correcto en cada facción.", "Que Cerca de ti enseña el instructor de clase y los objetivos de la zona, sin repetidos." },
  }, en = { resumen = "Travel: more reliable flights, inn, hearthstone, transport and Nearby. Test build.", grupos = {
      { t = "Travel", "A flight point only counts as discovered when the game reports it as known, and if two flight masters match the same spot neither is marked.", "The suggested inn keeps yours if you are already bound to one in the zone; otherwise it suggests the one closest to the coming steps.", "The hearthstone says if you do not carry it or its status is unknown.", "When going to another continent, or to a zone with a direct transport, the notice says which boat, zeppelin, tram or skyship to take, where it leaves from and where it arrives, by faction." },
