  { v = "9.7.7.2", resumen = "La guía reconoce la rama en la que tienes tus talentos y revisión de las profesiones. Versión de prueba.", grupos = {
      { t = "Talentos", "Las ramas de arriba de la pestaña Talentos enseñan los puntos que tienes de verdad en cada una, no los del plan.", "Si tienes casi todos tus puntos en otra rama que la del plan (por ejemplo Furia con el plan de Armas), la guía pasa sola a esa especialización, te pide el siguiente talento de esa rama y lo dice en el chat.", "Si después eliges otra a mano con el botón Especialización, la guía la respeta." },
      { t = "Profesiones", "Encantamiento, Herrería, Ingeniería, Peletería y Cocina: rangos de recetas, instructores, vendedores y planes alternativos revisados con fuentes de Forever. Las cantidades siguen siendo estimaciones.", "Herboristería y Desuello: tramos más cortos según tu habilidad, con qué recoger y dónde, e instructores por facción. Los circuitos siguen siendo orientativos.", "Pesca: cañas, comida, campamentos, el concurso de Tuercespina y los peces que te faltan para Cocina y Alquimia." },
      { t = "Falta probar en el juego", "Que las ramas de arriba enseñan los mismos puntos que la ventana de talentos del juego y que la guía pasa a Furia con un guerrero que tiene los puntos en Furia.", "Los planes de profesiones revisados y los consejos de Herboristería, Desuello y Pesca." },
  }, en = { resumen = "The guide recognises the branch your talents are in, and a profession review. Test build.", grupos = {
      { t = "Talents", "The branches at the top of the Talents tab show the points you actually have in each one, not the plan's.", "If almost all your points are in a different branch from the plan's (for example Fury with the Arms plan), the guide switches to that specialization by itself, asks for that branch's next talent and says so in chat.", "If you then pick another one by hand with the Specialization button, the guide keeps it." },
      { t = "Professions", "Enchanting, Blacksmithing, Engineering, Leatherworking and Cooking: recipe ranges, trainers, vendors and alternative plans checked against Forever sources. Quantities are still estimates.", "Herbalism and Skinning: shorter brackets for your skill, what to gather and where, and trainers by faction. Routes are still approximate.", "Fishing: poles, food, camps, the Stranglethorn contest and the fish you still need for Cooking and Alchemy." },
      { t = "Still to test in game", "That the branches at the top show the same points as the game's talent window, and that the guide switches to Fury for a warrior with points in Fury.", "The reviewed profession plans and the Herbalism, Skinning and Fishing tips." },
