GL.NOVEDADES = NOVEDADES
GL.VERSION = NOVEDADES[1].v

local panel, scroll, hijo, barra
local titulos, lineas = {}, {}
local previa                          -- versión que usaste la última vez con este personaje (nil: primera vez)

------------------------------------------------------------------------
-- Pantalla de novedades (dentro de la ventana, como las opciones)
------------------------------------------------------------------------
local function Escribir(lista, n, fuente, texto, x, y, ancho)
  local fs = lista[n]
  if not fs then
    fs = GL.Texto(hijo, fuente)
    lista[n] = fs
  end
  fs:ClearAllPoints()
  fs:SetPoint("TOPLEFT", hijo, "TOPLEFT", x, -y)
  fs:SetWidth(ancho)
  fs:SetText(GL.Simbolos and GL.Simbolos(texto) or texto)   -- 9.4.2: ▲ ✔... como iconos
  fs:Show()
  return GL.Alto(fs, texto, 12, ancho)
end

local function Colocar()
  if not panel then return end
  local ancho = scroll:GetWidth() or 0
  if ancho <= 40 then ancho = 330 end
  hijo:SetWidth(ancho)
  local nt, nl, y = 0, 0, 0
  for v = 1, #NOVEDADES do
    local n = NOVEDADES[v]
    if GL.ingles and not n.en then   -- 9.4.2: en inglés, solo lo que está en inglés
      nl = nl + 1
      y = y + Escribir(lineas, nl, "GameFontHighlightSmall", C.GRIS .. "Older versions: only in Spanish, in NOVEDADES.txt." .. C.FIN, 0, y, ancho) + 5
      break
    end
    local cabecera = L"Versión " .. n.v
    if n.v == GL.VERSION then cabecera = cabecera .. C.VERDE .. L"  (la que tienes)" .. C.FIN end
    nt = nt + 1
    y = y + Escribir(titulos, nt, "GameFontNormal", cabecera, 0, y, ancho) + 2
    nl = nl + 1
    y = y + Escribir(lineas, nl, "GameFontHighlightSmall", C.GRIS .. Ver(n).resumen .. C.FIN, 0, y, ancho) + 5
    for g = 1, #Ver(n).grupos do
      local grupo = Ver(n).grupos[g]
      if grupo.t then
        nl = nl + 1
        y = y + Escribir(lineas, nl, "GameFontHighlightSmall", C.AZUL .. grupo.t .. C.FIN, 0, y, ancho) + 2
      end
      for i = 1, #grupo do
        nl = nl + 1
        Escribir(lineas, nl, "GameFontHighlightSmall", C.GRIS .. "-" .. C.FIN, 2, y, 10)
        nl = nl + 1
        y = y + Escribir(lineas, nl, "GameFontHighlightSmall", grupo[i], 12, y, ancho - 12) + 3
      end
      y = y + 3
    end
    y = y + 12
  end
  for i = nt + 1, #titulos do titulos[i]:Hide() end
  for i = nl + 1, #lineas do lineas[i]:Hide() end
  hijo:SetHeight(math.max(1, y))
  local maximo = math.max(0, math.floor(y - (scroll:GetHeight() or 0) + 0.5))
  barra:SetMinMaxValues(0, maximo)
  GL.Mostrar(barra, maximo > 0)
  local actual = barra:GetValue() or 0
  if actual > maximo then actual = maximo end
  barra:SetValue(actual)
  scroll:SetVerticalScroll(actual)
end

local function CrearPanel()
  local frame = GL.frame
  if panel or not frame then return end
  panel = CreateFrame("Frame", nil, frame)
  panel:SetPoint("TOPLEFT", frame, "TOPLEFT", GL.IZQ, -(GL.ARRIBA + GL.ALTO_SUB))   -- debajo de las subpestañas
  panel:SetPoint("BOTTOMRIGHT", frame, "BOTTOMRIGHT", -GL.MARGEN, GL.ABAJO)
  panel:Hide()
  local titulo = GL.Texto(panel, "GameFontNormalLarge")
  titulo:SetPoint("TOPLEFT", panel, "TOPLEFT", 0, 0)
  titulo:SetText(L"Novedades")
  local nota = GL.Texto(panel, "GameFontHighlightSmall", "RIGHT")
  nota:SetPoint("TOPRIGHT", panel, "TOPRIGHT", 0, -4)
  nota:SetText(C.GRIS .. L"Lo nuevo de cada versión" .. C.FIN)

  scroll = CreateFrame("ScrollFrame", nil, panel)
  scroll:SetPoint("TOPLEFT", panel, "TOPLEFT", 0, -28)
  scroll:SetPoint("BOTTOMRIGHT", panel, "BOTTOMRIGHT", -16, 0)
  hijo = CreateFrame("Frame", nil, scroll)
  hijo:SetWidth(330)
  hijo:SetHeight(1)
  scroll:SetScrollChild(hijo)

  -- barra para bajar: también se usa la rueda del ratón
  barra = CreateFrame("Slider", nil, panel)
  barra:SetOrientation("VERTICAL")
  barra:SetWidth(10)
  barra:SetPoint("TOPRIGHT", panel, "TOPRIGHT", 0, -28)
  barra:SetPoint("BOTTOMRIGHT", panel, "BOTTOMRIGHT", 0, 0)
  local pista = barra:CreateTexture(nil, "BACKGROUND")
  pista:SetPoint("TOP", barra, "TOP", 0, 0)
  pista:SetPoint("BOTTOM", barra, "BOTTOM", 0, 0)
  pista:SetWidth(4)
  pista:SetColorTexture(1, 1, 1, 0.12)
  local pulgar = barra:CreateTexture(nil, "OVERLAY")
  pulgar:SetWidth(8)
  pulgar:SetHeight(28)
  pulgar:SetColorTexture(0.41, 0.8, 0.94, 0.85)
  barra:SetThumbTexture(pulgar)
  barra:SetMinMaxValues(0, 0)
  barra:SetValueStep(1)
  barra:SetValue(0)
  barra:EnableMouse(true)
  barra:SetScript("OnValueChanged", function(self, v) scroll:SetVerticalScroll(v) end)
  scroll:EnableMouseWheel(true)
  scroll:SetScript("OnMouseWheel", function(self, delta)
    local minimo, maximo = barra:GetMinMaxValues()
    local v = (barra:GetValue() or 0) - delta * 36
    if v < minimo then v = minimo end
    if v > maximo then v = maximo end
    barra:SetValue(v)
  end)
  GL.modos.novedades = { panel = panel, refrescar = Colocar }
end

function GL.AbrirNovedades()
  local db = GuiaAventureroDB
  if db.compacto and GL.SalirCompacto then GL.SalirCompacto() end
  if GL.frame then GL.frame:Show(); db.oculto = false end
  if barra then barra:SetValue(0) end
  GL.AbrirModo("novedades")
end

------------------------------------------------------------------------
-- Aviso en el chat cuando el addon se ha actualizado
------------------------------------------------------------------------
-- Las variables guardadas se cargan justo antes de ADDON_LOADED: ahí se ve con qué versión jugaste la última vez.
local carga = CreateFrame("Frame")
GL.Evento(carga, "ADDON_LOADED")
carga:SetScript("OnEvent", function(self, event, nombre)
  if nombre ~= nombreAddon then return end
  self:UnregisterEvent("ADDON_LOADED")
  if type(GuiaAventureroDB) == "table" and next(GuiaAventureroDB) ~= nil then
    previa = GuiaAventureroDB.version or "3.2"   -- hasta la 3.2 no se guardaba la versión
  end
end)

table.insert(GL.alIniciar, function()
  CrearPanel()
  local db = GuiaAventureroDB
  if GL.ui and GL.ui.autor then
    GL.ui.autor:SetText(C.GRIS .. L"Versión " .. GL.VERSION .. "  ·  " .. GL.AUTOR .. C.FIN)
  end
  if previa and previa ~= GL.VERSION then
    -- si te has saltado alguna versión, también se dice lo de esas (como mucho las tres últimas)
    local function Avisar()
      local resumenes = {}
      for i = 1, #NOVEDADES do
        local n = NOVEDADES[i]
        if n.v == previa or #resumenes >= 3 then break end
        table.insert(resumenes, (i > 1 and (n.v .. ": ") or "") .. Ver(n).resumen)
      end
      GL.Mensaje(L"se ha actualizado a la versión " .. GL.VERSION .. ". " .. table.concat(resumenes, " ") ..
        L" Escribe /ga novedades para verlo todo.")
    end
    if C_Timer and C_Timer.After then C_Timer.After(3, Avisar) else Avisar() end
  end
  db.version = GL.VERSION
end)

GL.comandos["novedades"] = function() GL.AbrirNovedades() end
GL.comandos["cambios"] = GL.comandos["novedades"]
GL.comandos["version"] = function()
  GL.Mensaje(L"versión " .. GL.VERSION .. L". /ga novedades para ver lo nuevo de cada versión.")
end
GL.comandos["versión"] = GL.comandos["version"]
